<?php
use App\Models\Release;
$releaseOffset=max(0,(int)($_GET['offset']??0));$releaseArchived=!empty($_GET['archived']);
$releasePage=Release::page((int)$project['id'],$releaseOffset,50,$releaseArchived);
$selectedRelease=!empty($_GET['release'])?Release::find((int)$_GET['release']):null;
if($selectedRelease && (int)$selectedRelease['project_id']!==(int)$project['id']) throw new InvalidArgumentException('Cette version appartient à un autre projet.');
$releaseCanEdit=$user['role']!=='viewer';
?>
<div data-release-space class="release-space"><div class="release-toolbar"><a class="button subtle" href="/releases?project=<?= (int)$project['id'] ?>&archived=<?= $releaseArchived?0:1 ?>"><?= $releaseArchived?'Versions actives':'Versions archivées' ?></a><p class="help-text">Les versions regroupent les tickets ciblés. Les livraisons sont déclarées explicitement, séparément du statut des tickets et des pull requests.</p></div>
<?php if($releaseCanEdit): ?><details class="panel release-create"><summary><?= icon('plus') ?>Créer une version</summary><form method="post" action="/releases" class="stack details-content" data-tracking-form><?= csrf() ?><input type="hidden" name="project_id" value="<?= (int)$project['id'] ?>"><div class="inline-fields"><label>Nom de version<input name="name" required maxlength="120" placeholder="Ex. : 2.4.0"></label><label>Date cible<input type="date" name="target_date"></label></div><label>Objectif<textarea name="description" rows="2" maxlength="10000"></textarea></label><button class="button primary">Créer la version</button></form></details><?php endif; ?>
<div class="release-layout"><section class="panel release-index"><h2><?= $releaseArchived?'Versions archivées':'Versions du projet' ?></h2><?php foreach($releasePage['releases'] as $r): ?><a class="release-card <?= $selectedRelease && $selectedRelease['id']===$r['id']?'selected':'' ?>" href="/releases?project=<?= (int)$project['id'] ?>&release=<?= (int)$r['id'] ?>&archived=<?= $releaseArchived?1:0 ?>"><strong><?= e($r['name']) ?></strong><span><?= (int)$r['ticket_count'] ?> ticket(s) · <?= e($r['target_date']?:'Sans date cible') ?></span><?php foreach(Release::ENVIRONMENTS as $environment=>$label): ?><small><?= e($label) ?> : <?= e($r['delivery_state'][$environment]?Release::OUTCOMES[$r['delivery_state'][$environment]['outcome']]:'Non déclarée') ?></small><?php endforeach; ?></a><?php endforeach; if(!$releasePage['releases']): ?><p class="empty-state">Aucune version pour le moment.</p><?php endif; ?>
<?php if($releaseOffset || $releasePage['total']>$releasePage['limit']): ?><nav class="pagination"><?php if($releaseOffset): ?><a href="<?= e(query_url('/releases',['project'=>$project['id'],'archived'=>(int)$releaseArchived,'offset'=>max(0,$releaseOffset-50)])) ?>">Précédent</a><?php endif; ?><span><?= $releasePage['total'] ?> version(s)</span><?php if($releaseOffset+50<$releasePage['total']): ?><a href="<?= e(query_url('/releases',['project'=>$project['id'],'archived'=>(int)$releaseArchived,'offset'=>$releaseOffset+50])) ?>">Suivant</a><?php endif; ?></nav><?php endif; ?></section>
<?php if($selectedRelease): $release=$selectedRelease;$deliveries=Release::deliveries((int)$release['id'],max(0,(int)($_GET['delivery_offset']??0)));$releaseTicketPage=max(1,(int)($_GET['ticket_page']??1));$releaseFilters=['release'=>$release['id'],'pause'=>'all'];$releaseTickets=App\Services\Query::tickets((int)$project['id'],$releaseFilters,50,($releaseTicketPage-1)*50);$releaseTicketCount=App\Services\Query::count((int)$project['id'],$releaseFilters); ?>
<div class="release-detail"><section class="panel"><div class="panel-header"><div><h2><?= e($release['name']) ?><?= $release['archived']?' · Archivée':'' ?></h2><p>Date cible : <?= e($release['target_date']?:'Non renseignée') ?></p></div><?= icon('folder') ?></div><p class="tracking-text"><?= e($release['description']) ?></p><div class="tracking-metrics"><?php foreach(Release::ENVIRONMENTS as $environment=>$label): $d=$release['delivery_state'][$environment]; ?><div><small><?= e($label) ?></small><strong class="delivery-state <?= $d?'delivery-'.$d['outcome']:'' ?>"><?= e($d?Release::OUTCOMES[$d['outcome']]:'Non déclarée') ?></strong><?php if($d): ?><small><?= e($d['reference']) ?><br><?= e($d['created_at']) ?> UTC</small><?php endif; ?></div><?php endforeach; ?></div>
<?php if($releaseCanEdit): ?><details><summary class="text-button">Modifier la version</summary><form action="/releases" method="post" class="stack details-content" data-tracking-form><?= csrf() ?><input type="hidden" name="id" value="<?= (int)$release['id'] ?>"><input type="hidden" name="project_id" value="<?= (int)$project['id'] ?>"><input type="hidden" name="version" value="<?= (int)$release['version'] ?>"><label>Nom<input name="name" value="<?= e($release['name']) ?>" required maxlength="120"></label><label>Date cible<input type="date" name="target_date" value="<?= e($release['target_date']) ?>"></label><label>Objectif<textarea name="description" rows="3" maxlength="10000"><?= e($release['description']) ?></textarea></label><input type="hidden" name="archived" value="0"><label class="check-label"><input type="checkbox" name="archived" value="1" <?= $release['archived']?'checked':'' ?>>Version archivée</label><button class="button subtle">Enregistrer la version</button></form></details><?php endif; ?></section>
<section class="panel"><div class="panel-header"><div><h2>Tickets ciblés</h2><p><?= $releaseTicketCount ?> ticket(s), y compris les tickets en pause. L’affectation se fait depuis « Modifier » dans le ticket.</p></div><a class="button subtle" href="/list?project=<?= (int)$project['id'] ?>&release=<?= (int)$release['id'] ?>&pause=all">Ouvrir la liste</a></div><div class="release-tickets"><?php foreach($releaseTickets as $t): ?><a href="<?= e(ticket_url((int)$t['id'])) ?>"><span class="ticket-key"><?= e($t['key']) ?></span><strong><?= e($t['title']) ?></strong><?= status_badge($t['status'],(int)$project['id']) ?><small><?= (int)$t['progress_percent'] ?> %</small></a><?php endforeach; if(!$releaseTickets): ?><p class="muted">Aucun ticket associé.</p><?php endif; ?></div>
<?php if($releaseTicketPage>1 || $releaseTicketCount>$releaseTicketPage*50): ?><nav class="pagination"><?php if($releaseTicketPage>1): ?><a href="<?= e(query_url('/releases',$_GET,['ticket_page'=>$releaseTicketPage-1])) ?>">Précédent</a><?php endif; ?><span>Page <?= $releaseTicketPage ?></span><?php if($releaseTicketCount>$releaseTicketPage*50): ?><a href="<?= e(query_url('/releases',$_GET,['ticket_page'=>$releaseTicketPage+1])) ?>">Suivant</a><?php endif; ?></nav><?php endif; ?></section>
<section class="panel"><div class="panel-header"><div><h2>Livraisons</h2><p>Historique conservé : environnement, résultat, référence et auteur. Une fusion Git seule ne crée aucune livraison.</p></div><?= icon('external') ?></div>
<?php if($releaseCanEdit && !$release['archived']): ?><details class="tracking-add"><summary class="button subtle">Déclarer une livraison</summary><form action="/releases/<?= (int)$release['id'] ?>/deliveries" method="post" class="stack details-content" data-tracking-form><?= csrf() ?><input type="hidden" name="version" value="<?= (int)$release['version'] ?>"><div class="inline-fields"><label>Environnement<select name="environment"><?php foreach(Release::ENVIRONMENTS as $value=>$text): ?><option value="<?= e($value) ?>"><?= e($text) ?></option><?php endforeach; ?></select></label><label>Résultat<select name="outcome"><?php foreach(Release::OUTCOMES as $value=>$text): ?><option value="<?= e($value) ?>"><?= e($text) ?></option><?php endforeach; ?></select></label></div><label>Référence livrée<input name="reference" required maxlength="240" placeholder="Tag, SHA du commit ou numéro de build"></label><label>Note<textarea name="note" rows="2" maxlength="2000"></textarea></label><button class="button primary">Enregistrer la livraison</button></form></details><?php endif; ?>
<?php foreach($deliveries['entries'] as $d): ?><article class="delivery-entry"><header><strong><?= e(Release::ENVIRONMENTS[$d['environment']]) ?></strong><span class="delivery-state delivery-<?= e($d['outcome']) ?>"><?= e(Release::OUTCOMES[$d['outcome']]) ?></span></header><p class="tracking-text"><?= e($d['reference']) ?></p><?php if($d['note']!==''): ?><p class="tracking-text"><?= e($d['note']) ?></p><?php endif; ?><small><?= e($d['actor_name'].' · '.$d['created_at']) ?> UTC</small></article><?php endforeach; if(!$deliveries['entries']): ?><p class="empty-state">Aucune livraison déclarée.</p><?php endif; ?>
<?php if($deliveries['offset'] || $deliveries['total']>$deliveries['limit']): ?><nav class="pagination"><?php if($deliveries['offset']): ?><a href="<?= e(query_url('/releases',$_GET,['delivery_offset'=>max(0,$deliveries['offset']-$deliveries['limit'])])) ?>">Plus récentes</a><?php endif; ?><span><?= $deliveries['total'] ?> livraison(s)</span><?php if($deliveries['offset']+$deliveries['limit']<$deliveries['total']): ?><a href="<?= e(query_url('/releases',$_GET,['delivery_offset'=>$deliveries['offset']+$deliveries['limit']])) ?>">Plus anciennes</a><?php endif; ?></nav><?php endif; ?></section></div>
<?php else: ?><section class="panel empty-state">Sélectionnez une version pour consulter ses tickets et ses livraisons.</section><?php endif; ?></div></div>
